#define CONV1D_KERNEL               15
#define CONV1D_STRIDE               2
#define CONV1D_PAD                  7
#define CONV1D_OUT_LEN              125 /* (250 + 2*7 - 15)/2 + 1 = 125 */

/* Layer 1b: MaxPool1D (kernel=2, stride=2) */
